                                      builder: (context, _) {
                                        return Icon(
                                          _isListeningVoice ? Icons.mic_rounded : Icons.mic_none_rounded,
                                          color: _isListeningVoice 
                                              ? AppTheme.bearColor.withValues(alpha: 0.5 + 0.5 * _flashAnimation.value) 
                                              : AppTheme.primaryCyan,
                                          size: 20,
                                        );
                                      },
                                    ),
                                  ),
                                ],
                              );
